#define _POSIX_C_SOURCE 200809L
#include "recursant/stream_tools.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static size_t attempts, fail_at, live;
static int hit, persistent;
static void *alloc(size_t n) {
    ++attempts;
    if (fail_at && (attempts == fail_at || (persistent && attempts > fail_at))) { hit=1; return NULL; }
    void *p=malloc(n); if (p) ++live; return p;
}
static void release(void *p) { if(p) { assert(live); --live; free(p); } }
static void oom(void) {
    json_set_alloc_funcs(alloc,release);
    json_error_t e;
    json_t *a=json_loads("[{\"index\":0,\"function\":{\"arguments\":\"a\\u0000b\",\"name\":\"α\"}}]",JSON_ALLOW_NUL,&e);
    json_t *b=json_loads("[{\"index\":0,\"id\":\"opaque id\",\"type\":\"function\",\"function\":{\"arguments\":\"\\n\",\"name\":\"🙂\"}}]",0,&e);
    assert(a&&b); size_t baseline=live;
    for(persistent=0;persistent<2;++persistent) {
        size_t rejected=0;
        for(size_t i=1;i<10000;++i) {
            attempts=0; fail_at=i; hit=0;
            rc_stream_tools *s=rc_stream_tools_new(); json_t *out=NULL;
            if(s && rc_stream_tools_feed(s,a) && rc_stream_tools_feed(s,b)) out=rc_stream_tools_complete(s);
            fail_at=0;
            if(hit) { ++rejected; assert(!out); if(s) { assert(rc_stream_tools_failed(s)); assert(!rc_stream_tools_feed(s,b)); assert(!rc_stream_tools_complete(s)); } }
            else { assert(out); assert(!rc_stream_tools_failed(s)); }
            rc_stream_tools_free(s); json_decref(out); assert(live==baseline);
            if(!hit) break;
            assert(i<9999);
        }
        printf("independent OOM mode=%d fail-closed-points=%zu\n",persistent,rejected);
    }
    json_decref(a); json_decref(b); assert(!live); json_set_alloc_funcs(malloc,free);
}
int main(int argc,char **argv) {
    if(argc>1 && !strcmp(argv[1],"oom")) { oom(); return 0; }
    char *line=NULL; size_t cap=0;
    while(getline(&line,&cap,stdin)>0) {
        json_error_t e;
        json_t *scenario=json_loads(line,JSON_REJECT_DUPLICATES|JSON_ALLOW_NUL,&e);
        if(!scenario) { puts("{\"decode_rejected\":true}"); continue; }
        json_t *ds=json_object_get(scenario,"deltas"); assert(json_is_array(ds));
        rc_stream_tools *s=rc_stream_tools_new(); assert(s);
        json_t *results=json_array(); assert(results);
        const char *badfield=json_string_value(json_object_get(scenario,"invalid_utf8"));
        size_t i; json_t *d;
        json_array_foreach(ds,i,d) {
            if(badfield && i==0) {
                json_t *target=json_array_get(d,0);
                if(strcmp(badfield,"id")) target=json_object_get(target,"function");
                assert(!json_object_set_new(target,badfield,json_stringn_nocheck("\xc0\x80",2)));
            }
            if(i==0 && json_is_integer(json_object_get(scenario,"nul_key"))) {
                json_t *target=json_array_get(d,0);
                if(json_integer_value(json_object_get(scenario,"nul_key"))) target=json_object_get(target,"function");
                assert(!json_object_setn_new(target,"id\0evil",7,json_null()));
            }
            bool ok=rc_stream_tools_feed(s,d);
            assert(!json_array_append_new(results,json_boolean(ok)));
            if(json_is_true(json_object_get(scenario,"mutate"))) {
                size_t j; json_t *call;
                json_array_foreach(d,j,call) {
                    json_t *v=json_object_get(call,"id"); if(json_is_string(v)) assert(!json_string_set(v,"MUTATED"));
                    json_t *f=json_object_get(call,"function");
                    v=json_object_get(f,"name"); if(json_is_string(v)) assert(!json_string_set(v,"MUTATED"));
                    v=json_object_get(f,"arguments"); if(json_is_string(v)) assert(!json_string_set(v,"MUTATED"));
                }
            }
        }
        json_decref(scenario);
        json_t *out=rc_stream_tools_complete(s);
        bool failed=rc_stream_tools_failed(s);
        json_t *empty=json_array(); assert(empty);
        assert(!rc_stream_tools_feed(s,empty)); json_decref(empty);
        assert(rc_stream_tools_failed(s)); assert(!rc_stream_tools_complete(s));
        rc_stream_tools_free(s);
        json_t *result=json_pack("{s:o,s:b,s:O}","feeds",results,"failed",failed,"out",out?out:json_null()); assert(result);
        json_decref(out);
        char *wire=json_dumps(result,JSON_COMPACT); assert(wire); puts(wire); free(wire); json_decref(result);
    }
    free(line); return 0;
}

