import json, copy, pathlib, subprocess, hashlib
ROOT=pathlib.Path(__file__).resolve().parent
BASE={'index':0,'id':'opaque| α/🙂','type':'function','function':{'name':'f','arguments':'{"x":1}'}}
cases=[]
def add(name,ds,feeds,out=None,**extra):
    cases.append({'name':name,'scenario':dict(deltas=ds,**extra),'expected':{'feeds':feeds,'failed':out is None,'out':out}})
def completed(c):
    c=copy.deepcopy(c); c.pop('index'); return c
def bad(name,c): add(name,[[c],[]],[False,False])
def good(name,c): add(name,[[c]],[True],[completed(c)])
good('positive baseline',BASE)
for field in ['index','id','type','function']:
    for value in [None,True,False,[],{},0,0.0,-1,32,2**63-1,-2**63,'','0','function\0','custom']:
        if field=='index' and type(value) is int and value==0: continue
        if field=='id' and type(value) is str and value and '\0' not in value: continue
        c=copy.deepcopy(BASE);c[field]=value;bad(f'type matrix {field} {value!r}',c)
for field in ['name','arguments']:
    for value in [None,True,False,[],{},0,0.0]:
        c=copy.deepcopy(BASE);c['function'][field]=value;bad(f'function type {field} {value!r}',c)
for field in ['id','type','name','arguments']:
    c=copy.deepcopy(BASE); target=c['function'] if field in ('name','arguments') else c;target.pop(field)
    add('no inferred '+field,[[c],[]],[True,True])
for key in ['', 'x|y', 'id\0suffix', 'index\0', 'success', 'status', 'finish_reason', 'reasoning']:
    for nested in [False,True]:
        c=copy.deepcopy(BASE);(c['function'] if nested else c)[key]=None;bad(f'unknown key {key!r} nested={nested}',c)
for c in cases:
    if c['name'].startswith('unknown key') and any('\0' in k for d in c['scenario']['deltas'] for item in d for target in [item,item.get('function',{})] for k in target):
        c['expected']={'decode_rejected':True}
for nested in [0,1]:
    add(f'programmatic NUL key nested={nested}',[[copy.deepcopy(BASE)],[]],[False,False],nul_key=nested)
for field in ['id','name','arguments']:
    add('programmatic invalid UTF8 '+field,[[copy.deepcopy(BASE)],[]],[False,False],invalid_utf8=field)
for field in ['id','name']:
    c=copy.deepcopy(BASE); (c if field=='id' else c['function'])[field]='before\0after';bad('NUL '+field,c)
c=copy.deepcopy(BASE);c['function']['arguments']='\0\n\r\tα🙂not JSON';good('opaque NUL UTF8 args',c)
c=copy.deepcopy(BASE);c['function']['arguments']='';good('explicit empty arguments',c)
c=copy.deepcopy(BASE);c['function']['name']='';add('empty final name',[[c]],[True])
add('empty stream',[[]],[True])
for idx in [1,31]:
    c=copy.deepcopy(BASE);c['index']=idx;add(f'sparse {idx}',[[c]],[True])
add('duplicate index chunk',[[BASE,BASE],[]],[False,False])
add('index-only',[[{'index':0}],[]],[False,False])
add('empty function',[[{'index':0,'function':{}}]],[False])
add('changed same-index id',[[BASE],[{'index':0,'id':'replacement'}],[]],[True,False,False])
add('partial ID is not concatenated',[[{'index':0,'id':'ab'}],[{'index':0,'id':'cd'}]],[True,False])
add('repeated full identity',[[BASE],[{'index':0,'id':BASE['id'],'type':'function'}]],[True,True],[completed(BASE)])
c=completed(BASE);c['function']['name']*=2;c['function']['arguments']*=2
add('repeated fragments concatenate',[[BASE],[BASE]],[True,True],[c])
c1=copy.deepcopy(BASE);c1['index']=1
add('duplicate final IDs',[[BASE],[c1]],[True,True])
add('no rollback on mixed good-bad delta',[[BASE,{'index':1,'id':None}],[]],[False,False])
add('mutation of borrowed inputs',[[copy.deepcopy(BASE)]],[True],[completed(BASE)],mutate=True)
# Every character-boundary partition of UTF8/NUL data, with ID/type arriving last.
name='α🙂abc';args=' \t{\"x\":\0🙂α\n}trailing'
for n in range(len(name)+1):
    for a in range(len(args)+1):
        ds=[[{'index':0,'function':{'name':name[:n],'arguments':args[:a]}}],[{'index':0,'function':{'name':name[n:],'arguments':args[a:]}}],[{'index':0,'id':BASE['id'],'type':'function'}]]
        expected=completed(BASE);expected['function']={'name':name,'arguments':args}
        add(f'partition {n}/{a}',ds,[True]*3,[expected])
cs=[]
for i in range(32):
    c=copy.deepcopy(BASE);c['index']=i;c['id']=f'id{i}';cs.append(c)
add('32 reverse order', [list(reversed(cs))],[True],list(map(completed,cs)))
add('33 entries rejected',[cs+[BASE]],[False])
for n in [128,129]:
    c=copy.deepcopy(BASE);c['id']='i'*n
    if n==128:good('exact ID bound',c)
    else:bad('ID overflow',c)
c=copy.deepcopy(BASE);c['id']='i';c['function']={'name':'n','arguments':''}
overhead=len(json.dumps([completed(c)],ensure_ascii=False,separators=(',',':')).encode())
for excess in [0,1]:
    d=copy.deepcopy(c);d['function']['arguments']='a'*(32768-overhead+excess)
    add(f'wire capacity {excess}',[[d]],[True],[completed(d)] if not excess else None)
for length in [32758,32759]:
    d=copy.deepcopy(c);d['function']['arguments']='a'*length
    add(f'retained capacity {length}',[[d],[]],[length==32758,length==32758])
d=copy.deepcopy(c);d['function']['arguments']='\0'*5500
add('escape expansion bound',[[d]],[True])
# Duplicate keys must be detected before object collapse, including escaped equivalents.
for raw in ['{"deltas":[[{"index":0,"index":1,"id":"i"}]]}', '{"deltas":[[{"index":0,"id":"a","id":"b"}]]}', '{"deltas":[[{"index":0,"id":"a","\\u0069d":"b"}]]}', '{"deltas":[[{"index":0,"function":{"name":"a","name":"b"}}]]}', '{"deltas":[[{"index":9223372036854775808,"id":"i"}]]}']:
    cases.append({'name':'strict decoder '+raw,'raw':raw,'expected':{'decode_rejected':True}})
(ROOT/'cases.json').write_text(json.dumps(cases,ensure_ascii=False,indent=2))
wire=''.join((c.get('raw') or json.dumps(c['scenario'],ensure_ascii=False,separators=(',',':')))+'\n' for c in cases)
records=[]
for mode in ['normal','asan']:
    cmd=['docker','run','--rm','-i','--network','none','-v',f'{ROOT}:/out:ro','recursant-v4-dev:local','sh','-c',f'ASAN_OPTIONS=detect_leaks=1:halt_on_error=1 UBSAN_OPTIONS=halt_on_error=1 /out/probe-{mode}']
    p=subprocess.run(cmd,input=wire,text=True,capture_output=True)
    rows=p.stdout.splitlines(); failures=[]
    for i,c in enumerate(cases):
        observed=json.loads(rows[i]) if i<len(rows) else None
        if observed!=c['expected']:failures.append({'name':c['name'],'expected':c['expected'],'observed':observed})
    result={'mode':mode,'argv':cmd,'exit_code':p.returncode,'case_count':len(cases),'result_count':len(rows),'failures':failures,'stderr':p.stderr,'stdout_sha256':hashlib.sha256(p.stdout.encode()).hexdigest()}
    (ROOT/f'probe-{mode}.jsonl').write_text(p.stdout)
    records.append(result)
    print(json.dumps(result,ensure_ascii=False))
(ROOT/'probe-results.json').write_text(json.dumps(records,indent=2,ensure_ascii=False))
assert all(r['exit_code']==0 and r['case_count']==r['result_count'] and not r['failures'] and not r['stderr'] for r in records)
